head.b:skin:
/*-----------------------------------------------
Blogger Theme Skin for Wacana Style (Responsive Revision)
Theme Color: Carbon Black & Racing Red (Matching Logo)
-----------------------------------------------*/

/* Hanya di halaman HOME: sembunyikan konten bawaan Blogger agar landing page tampil penuh */
body.index #blogger-default-section, 
body.index .main-inner, 
body.index .blog-posts, 
body.index .status-msg-wrap, 
body.index .no-posts,
body.index .feed-links {
    display: none !important;
    height: 0 !important;
    visibility: hidden !important;
    opacity: 0 !important;
}

/* Di halaman selain HOME (halaman statis, postingan, dll): sembunyikan konten landing page */
body.static_page .landing-content,
body.item .landing-content,
body.archive .landing-content,
body.error_page .landing-content {
    display: none !important;
}

/* Styling konten halaman statis / postingan agar tampil rapi di background gelap */
body.static_page .main-inner,
body.item .main-inner,
body.archive .main-inner,
body.error_page .main-inner {
    display: block !important;
    height: auto !important;
    visibility: visible !important;
    opacity: 1 !important;
    max-width: 900px;
    margin: 0 auto;
    padding: 120px 20px 60px;
    color: #f3f4f6;
    font-family: 'Inter', sans-serif;
    line-height: 1.7;
}

body.static_page .post,
body.item .post,
body.archive .post,
body.error_page .post {
    background: #121215;
    border: 1px solid #27272a;
    border-radius: 16px;
    padding: 30px;
}

body.static_page .post h1,
body.static_page .post h2,
body.static_page .post h3,
body.item .post h1,
body.item .post h2,
body.item .post h3,
body.archive .post h1,
body.archive .post h2,
body.archive .post h3,
body.error_page .post h1,
body.error_page .post h2,
body.error_page .post h3 {
    font-family: 'Montserrat', sans-serif;
    color: #ffffff;
    font-weight: 800;
}

body.static_page .post a,
body.item .post a,
body.archive .post a,
body.error_page .post a {
    color: #f87171;
}

body.static_page .post img,
body.item .post img,
body.archive .post img,
body.error_page .post img {
    max-width: 100%;
    height: auto;
    border-radius: 10px;
}

body.static_page .post-title,
body.item .post-title,
body.archive .post-title,
body.error_page .post-title {
    font-size: 2rem;
    margin-bottom: 20px;
    color: #fff;
}

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
/*  */

// Fungsi Toggle untuk Drawer Sidebar Menu (Berlaku Desktop dan HP)
function toggleMenu() {
    const drawer = document.getElementById('sideDrawer');
    const overlay = document.getElementById('drawerOverlay');

    if (drawer.classList.contains('translate-x-full')) {
        // Tampilkan Drawer
        drawer.classList.remove('translate-x-full');
        overlay.classList.remove('hidden');
        setTimeout(() => { overlay.classList.add('opacity-100'); }, 10);
    } else {
        // Sembunyikan Drawer
        drawer.classList.add('translate-x-full');
        overlay.classList.remove('opacity-100');
        setTimeout(() => { overlay.classList.add('hidden'); }, 300);
    }
}

// Animasi Scroll Reveal untuk Kartu Peraturan (IntersectionObserver dengan staggered delay)
(function() {
    var revealEls = document.querySelectorAll('.reveal');
    if (!('IntersectionObserver' in window)) {
        revealEls.forEach(function(el) { el.classList.add('revealed'); });
        return;
    }
    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry, i) {
            if (entry.isIntersecting) {
                var el = entry.target;
                var index = Array.prototype.indexOf.call(revealEls, el);
                setTimeout(function() {
                    el.classList.add('revealed');
                }, (index % 4) * 80);
                observer.unobserve(el);
            }
        });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    revealEls.forEach(function(el) { observer.observe(el); });
})();

