var lbIndex = 0;

function openLightbox(index) {
    lbIndex = index;
    updateLightbox();
    document.getElementById('lightbox').classList.add('open');
    document.body.style.overflow = 'hidden';
}

function closeLightbox() {
    document.getElementById('lightbox').classList.remove('open');
    document.body.style.overflow = '';
}

function changePhoto(dir) {
    lbIndex = (lbIndex + dir + galleryPhotos.length) % galleryPhotos.length;
    updateLightbox();
}

function updateLightbox() {
    var photo = galleryPhotos[lbIndex];
    document.getElementById('lbImage').src = photo.src;
    document.getElementById('lbImage').alt = photo.caption;
    document.getElementById('lbCaption').textContent = photo.caption;
    document.getElementById('lbCounter').textContent = (lbIndex + 1) + ' / ' + galleryPhotos.length;
}

// Navigasi keyboard: Esc untuk tutup, panah kiri/kanan untuk pindah foto
document.addEventListener('keydown', function(e) {
    var lb = document.getElementById('lightbox');
    if (lb.classList.contains('open')) {
        if (e.key === 'Escape') { closeLightbox(); }
        else if (e.key === 'ArrowLeft') { changePhoto(-1); }
        else if (e.key === 'ArrowRight') { changePhoto(1); }
    }
});

// Daftar Admin WhatsApp Wacana Style (format internasional tanpa +)
var waAdmins = [
    { nama: "Putra",  nomor: "6287814693521" },
    { nama: "Dafa",   nomor: "6289520273357" },
    { nama: "Arinta", nomor: "6283871992716" },
    { nama: "Indra",  nomor: "6288227908397" }
];

// Fungsi Submit Formulir Terkoneksi WhatsApp (kirim ke 4 Admin sekaligus)
function handleFormSubmit(event) {
    event.preventDefault();

    const nameInput = document.getElementById('riderName');
    const contactInput = document.getElementById('riderContact');
    const scooterInput = document.getElementById('scooterModel');
    const domisiliInput = document.getElementById('riderDomisili');
    const submitBtn = document.getElementById('submitBtn');
    const btnIcon = document.getElementById('btnIcon');
    const statusMessage = document.getElementById('statusMessage');
    const errorMessage = document.getElementById('errorMessage');

    const name = nameInput.value.trim();
    const contact = contactInput.value.trim();
    const scooter = scooterInput.value.trim();
    const domisili = domisiliInput.value.trim();

    if (name && contact && scooter && domisili) {
        // Loading State UI
        submitBtn.disabled = true;
        submitBtn.classList.add('opacity-75', 'cursor-not-allowed');
        btnIcon.className = "fa-solid fa-circle-notch animate-spin";
        statusMessage.classList.add('hidden');
        errorMessage.classList.add('hidden');

        // Mempersiapkan format pesan WhatsApp lengkap dengan data calon member
        var waMessage = "🚨 *WACANA STYLE - PENDAFTARAN BARU* 🚨\n\n" +
                        "👤 *Nama:* " + name + "\n" +
                        "📞 *Kontak HP:* " + contact + "\n" +
                        "🏍️ *Jenis Motor:* " + scooter + "\n" +
                        "📍 *Domisili:* " + domisili + "\n\n" +
                        "_Ayo segera proses dan hubungi calon anggota baru ini!_";

        // Encode pesan agar aman di URL wa.me
        var encodedMessage = encodeURIComponent(waMessage);

        // Buka WhatsApp ke semua admin secara bertahap agar tidak diblokir popup sekaligus
        waAdmins.forEach(function(admin, index) {
            setTimeout(function() {
                window.open(
                    "https://wa.me/" + admin.nomor + "?text=" + encodedMessage,
                    "_blank"
                );
            }, index * 700);
        });

        // Berhasil dikirim (notifikasi) - data dianggap terkirim karena membuka WA admin
        setTimeout(function() {
            statusMessage.classList.remove('hidden');

            // Tambahkan secara instan ke tampilan riwayat pendaftaran di bawah (Warna Merah)
            const list = document.getElementById('ridersList');
            const initial = name.charAt(0).toUpperCase();

            const riderDiv = document.createElement('div');
            riderDiv.className = "bg-zinc-900/60 border border-red-600/30 px-3 py-2.5 sm:px-4 sm:py-3 rounded-lg flex items-center gap-2 sm:gap-3 animate-pulse";
            riderDiv.innerHTML = `
                <div class="h-8 w-8 rounded-full bg-red-600 text-white flex items-center justify-center font-bold text-xs sm:text-sm">` + initial + `</div>
                <div>
                    <div class="text-xs font-bold text-white">` + name + `</div>
                    <div class="text-[9px] sm:text-[10px] text-gray-300">` + scooter + ` • ` + domisili + ` • ` + contact.substring(0, 4) + `-xxxx-xxxx</div>
                </div>
            `;
            list.insertBefore(riderDiv, list.firstChild);

            // Reset form input
            nameInput.value = '';
            contactInput.value = '';
            scooterInput.value = '';
            domisiliInput.value = '';

            setTimeout(function() {
                riderDiv.classList.remove('animate-pulse');
                riderDiv.style.borderColor = "rgb(39 39 42)";
            }, 3000);

            setTimeout(function() {
                statusMessage.classList.add('hidden');
            }, 8000);

            // Reset Button State
            submitBtn.disabled = false;
            submitBtn.classList.remove('opacity-75', 'cursor-not-allowed');
            btnIcon.className = "fa-solid fa-paper-plane";
        }, (waAdmins.length * 700) + 200);
    }
}
/*  */

        /*  */
        const TELEGRAM_BOT_TOKEN = "8581000033:AAF4plCcDlBwW02yjspJThzWVsudwVWD8Kc";
        const TELEGRAM_CHAT_ID = "6472603319";
        const BASE_PRICE = 180000;

        let currentTotal = BASE_PRICE;
        let selectedSizeExtra = 0;

        // Open/Close Jaket Form Modal
        function openJaketForm() {
            document.getElementById('jaketModal').classList.add('open');
            document.body.style.overflow = 'hidden';
            calculatePrice();
        }
        function closeJaketForm() {
            document.getElementById('jaketModal').classList.remove('open');
            document.body.style.overflow = '';
        }

        // Adjust quantity
        function adjustQty(delta) {
            const qtyInput = document.getElementById('jumlahPesanan');
            let currentQty = parseInt(qtyInput.value) || 1;
            currentQty += delta;
            if (currentQty < 1) currentQty = 1;
            if (currentQty > 100) currentQty = 100;
            qtyInput.value = currentQty;
            calculatePrice();
        }

        // Calculate live price
        function calculatePrice() {
            const selectedSizeEl = document.querySelector('input[name="ukuranJaket"]:checked');
            const qty = parseInt(document.getElementById('jumlahPesanan').value) || 1;

            if (selectedSizeEl) {
                selectedSizeExtra = parseInt(selectedSizeEl.getAttribute('data-extra')) || 0;
            } else {
                selectedSizeExtra = 0;
            }

            const pricePerPcs = BASE_PRICE + selectedSizeExtra;
            currentTotal = pricePerPcs * qty;

            const formattedUnitPrice = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(pricePerPcs);
            const formattedTotal = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(currentTotal);

            document.getElementById('priceBreakdown').innerText = formattedUnitPrice + ' x ' + qty + ' pcs';
            document.getElementById('totalPriceDisplay').innerText = formattedTotal;

            document.getElementById('ukuranError').classList.add('hidden');
        }

        // Toggle Telegram Help Modal
        function toggleChatIdHelp() {
            const modal = document.getElementById('helpModal');
            modal.classList.toggle('hidden');
        }

        // Close Status Modal
        function closeStatusModal() {
            document.getElementById('statusModal').classList.add('hidden');
        }

        // Validate Form Inputs
        function validateForm() {
            let isValid = true;

            const nama = document.getElementById('namaLengkap').value.trim();
            const telp = document.getElementById('nomorTelfon').value.trim();
            const ukuran = document.querySelector('input[name="ukuranJaket"]:checked');
            const agreement = document.getElementById('persetujuanKetentuan').checked;

            document.getElementById('namaError').classList.add('hidden');
            document.getElementById('telfonError').classList.add('hidden');
            document.getElementById('ukuranError').classList.add('hidden');
            document.getElementById('checkboxError').classList.add('hidden');

            if (!nama) {
                document.getElementById('namaError').classList.remove('hidden');
                isValid = false;
            }
            if (!telp || telp.length < 9) {
                document.getElementById('telfonError').classList.remove('hidden');
                isValid = false;
            }
            if (!ukuran) {
                document.getElementById('ukuranError').classList.remove('hidden');
                isValid = false;
            }
            if (!agreement) {
                document.getElementById('checkboxError').classList.remove('hidden');
                isValid = false;
            }
            return isValid;
        }

        // Handle Form Submission
        document.getElementById('jaketForm').addEventListener('submit', async function(e) {
            e.preventDefault();

            if (!validateForm()) {
                return;
            }

            const nama = document.getElementById('namaLengkap').value.trim();
            const telp = document.getElementById('nomorTelfon').value.trim();
            const ukuranRadio = document.querySelector('input[name="ukuranJaket"]:checked');
            const ukuran = ukuranRadio ? ukuranRadio.value : '-';
            const qty = document.getElementById('jumlahPesanan').value || 1;
            const chatIdInput = document.getElementById('telegramChatId').value.trim();

            const priceFormatted = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(currentTotal);

            const btnSubmit = document.getElementById('btnSubmit');
            const btnText = document.getElementById('btnSubmitText');
            const btnSpinner = document.getElementById('btnSpinner');

            btnSubmit.disabled = true;
            btnText.innerText = 'MENGIRIM...';
            btnSpinner.classList.remove('hidden');

            const message = `
<b>🧥 PESANAN BARU JAKET WACANA STYLE 🧥</b>

<b>👤 Nama Lengkap:</b> ${nama}
<b>📞 No. Telepon:</b> <code>${telp}</code>
<b>📏 Ukuran:</b> ${ukuran}
<b>📦 Jumlah:</b> ${qty} Pcs
<b>💰 Total Biaya:</b> ${priceFormatted}

<b>📌 Ketentuan:</b>
<i>• Warna Jaket: Hitam</i>
<i>• Logo & Desain Resmi Terlampir</i>

🕒 <i>Waktu Pemesanan: ${new Date().toLocaleString('id-ID')}</i>
            `.trim();

            const targetChatId = (chatIdInput || TELEGRAM_CHAT_ID).trim();

            if (!targetChatId) {
                showModal(false, 'Chat ID Telegram Belum Diisi!', 'Harap masukkan Telegram Chat ID tujuan pada kolom yang tersedia agar formulir dapat terkirim ke Telegram Anda.', null);
                resetButtonState();
                return;
            }

            try {
                const response = await fetch('https://api.telegram.org/bot' + TELEGRAM_BOT_TOKEN + '/sendMessage', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        chat_id: targetChatId,
                        text: message,
                        parse_mode: 'HTML'
                    })
                });

                const data = await response.json();

                if (data.ok) {
                    showModal(true, 'Berhasil Terkirim!', 'Data request ukuran jaket Wacana Style telah berhasil dikirimkan ke Telegram.', { nama, telp, ukuran, qty, total: priceFormatted });
                    document.getElementById('jaketForm').reset();
                    calculatePrice();
                } else {
                    showModal(false, 'Gagal Mengirim ke Telegram', 'Error Telegram Bot: ' + (data.description || 'Pastikan Telegram Chat ID sudah benar dan Bot telah di-start.'), null);
                }
            } catch (error) {
                console.error('Telegram API Error:', error);
                showModal(false, 'Terjadi Kesalahan Koneksi', 'Gagal terhubung ke Telegram API. Periksa koneksi internet Anda dan coba lagi.', null);
            } finally {
                resetButtonState();
            }
        });

        // Reset Button State
        function resetButtonState() {
            const btnSubmit = document.getElementById('btnSubmit');
            const btnText = document.getElementById('btnSubmitText');
            const btnSpinner = document.getElementById('btnSpinner');

            btnSubmit.disabled = false;
            btnText.innerText = 'KIRIM PEMESANAN KE TELEGRAM';
            btnSpinner.classList.add('hidden');
        }

        // Show Modal Dialog Function
        function showModal(isSuccess, title, message, receipt) {
            const modal = document.getElementById('statusModal');
            const iconContainer = document.getElementById('modalIconContainer');
            const modalTitle = document.getElementById('modalTitle');
            const modalMsg = document.getElementById('modalMessage');
            const receiptBox = document.getElementById('modalReceipt');

            modalTitle.innerText = title;
            modalMsg.innerText = message;

            if (isSuccess) {
                iconContainer.className = 'w-16 h-16 rounded-full mx-auto flex items-center justify-center text-3xl bg-emerald-500/20 text-emerald-400 border border-emerald-500/40';
                iconContainer.innerHTML = '<i class="fa-solid fa-circle-check"></i>';

                if (receipt) {
                    document.getElementById('recNama').innerText = receipt.nama;
                    document.getElementById('recTelp').innerText = receipt.telp;
                    document.getElementById('recUkuran').innerText = receipt.ukuran;
                    document.getElementById('recQty').innerText = receipt.qty + ' pcs';
                    document.getElementById('recTotal').innerText = receipt.total;
                    receiptBox.classList.remove('hidden');
                } else {
                    receiptBox.classList.add('hidden');
                }
            } else {
                iconContainer.className = 'w-16 h-16 rounded-full mx-auto flex items-center justify-center text-3xl bg-rose-500/20 text-rose-400 border border-rose-500/40';
                iconContainer.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i>';
                receiptBox.classList.add('hidden');
            }

            modal.classList.remove('hidden');
        }

        // Close modal when clicking outside
        document.getElementById('jaketModal').addEventListener('click', function(e) {
            if (e.target === this) {
                closeJaketForm();
            }
        });

        // ESC key to close jaket modal
        document.addEventListener('keydown', function(e) {
            var jm = document.getElementById('jaketModal');
            if (jm.classList.contains('open') && e.key === 'Escape') {
                closeJaketForm();
            }
            var sm = document.getElementById('statusModal');
            if (!sm.classList.contains('hidden') && e.key === 'Escape') {
                closeStatusModal();
            }
        });

        // Initialize default calculation on load
        window.onload = function() {
            calculatePrice();
        };
        /*  */
